import { Fragment, useCallback, useEffect, useState } from "react";
import { api } from "./api";
import { ensureModuleStyles } from "./styles";

/**
 * Komponen demo modul Sample — semua mandiri (zero impor core).
 * React diambil dari host via shim (`src/shims/react.ts`), styling pakai
 * token CSS var host lewat `src/styles.ts`.
 */

interface SampleItem {
  id: number;
  name: string;
  description?: string | null;
  quantity?: number;
  price?: string | number;
  status?: string;
  created_at?: string;
}

function useSampleItems() {
  const [items, setItems] = useState<SampleItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(() => {
    api<{ data: SampleItem[] }>("/api/v1/sample")
      .then((res) => {
        if (res.ok) setItems(res.data?.data ?? []);
        else setError(res.error ?? "Gagal memuat");
      })
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  return { items, loading, error, reload: load };
}

function CountPills({ items }: { items: SampleItem[] }) {
  const count = items.length;
  return (
    <div
      className="spine-sts-grid"
      style={{ marginBottom: 10 }}
    >
      <div className="spine-sts-pill">
        <b>{count}</b>
        <span>Total item</span>
      </div>
    </div>
  );
}

/** Widget dashboard — ringkasan + 3 item terbaru (area dashboard.widgets). */
export function SampleWidget() {
  ensureModuleStyles();
  const { items, loading, error } = useSampleItems();

  return (
    <div className="spine-sts-card">
      <h3 className="spine-sts-title">Sample — ringkasan</h3>
      {error && <div className="spine-sts-muted">{error}</div>}
      {loading ? (
        <div className="spine-sts-empty">Memuat...</div>
      ) : (
        <Fragment>
          <CountPills items={items} />
          <ul className="spine-sts-list">
            {items.slice(0, 3).map((it) => (
              <li key={it.id} className="spine-sts-item">
                <span className="spine-sts-muted">#{it.id} — {it.name}</span>
              </li>
            ))}
          </ul>
        </Fragment>
      )}
    </div>
  );
}

/** Tab profil — daftar item sample (area profile.tabs). */
export function SampleTab() {
  ensureModuleStyles();
  const { items, loading, error } = useSampleItems();

  return (
    <div className="spine-sts-card">
      <h3 className="spine-sts-title">Sample</h3>
      {error && <div className="spine-sts-muted">{error}</div>}
      {loading ? (
        <div className="spine-sts-empty">Memuat...</div>
      ) : items.length === 0 ? (
        <div className="spine-sts-empty">Belum ada sample item.</div>
      ) : (
        <ul className="spine-sts-list">
          {items.map((it) => (
            <li key={it.id} className="spine-sts-item">
              <span>
                <span className="spine-sts-muted">#{it.id}</span>{" "}
                <span>{it.name}</span>
              </span>
              <span className="spine-sts-muted">
                {it.quantity ?? 0} x {it.price ?? 0}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/** Section profil — ringkas total item (area profile.sections). */
export function SampleSummary() {
  ensureModuleStyles();
  const { items, loading } = useSampleItems();

  if (loading) return null;

  return (
    <div className="spine-sts-card">
      <h3 className="spine-sts-title">Sample</h3>
      <p className="spine-sts-muted" style={{ margin: 0 }}>
        Total <b>{items.length}</b> sample item.
      </p>
      <a className="spine-sts-link" href="/sample">
        Buka Sample →
      </a>
    </div>
  );
}
