import {
  SampleSummary,
  SampleTab,
  SampleWidget,
} from "./components";
import type { ModuleContext, SpineModule } from "./types";

/**
 * Module frontend "sample" — pendamping modul backend dengan nama sama.
 * Contoh cara modul eksternal menyumbang UI ke area core tanpa mengubah kode
 * core: register context.ui.* dengan komponen milik sendiri.
 */
const module: SpineModule = {
  id: "sample",
  name: "Sample UI",
  version: "0.1.0",

  translations: {
    en: {
      "tabs.sample": "Sample",
      "sections.summary": "Sample Summary",
      "widgets.quickStats": "Sample — quick stats",
    },
    id: {
      "tabs.sample": "Contoh",
      "sections.summary": "Ringkasan Contoh",
      "widgets.quickStats": "Contoh — statistik cepat",
    },
  },

  register(ctx: ModuleContext) {
    const { module, i18n, ui } = ctx;

    // Terjemahan milik modul — core hanya resolve label (i18n.addTranslations).
    i18n.addTranslations("module." + module.id, {
      "tabs.sample": "Sample",
      "sections.summary": "Sample Summary",
      "widgets.quickStats": "Sample — quick stats",
    });

    ui.tabs.register({
      area: "profile.tabs",
      id: "sample",
      label: { namespace: "module." + module.id, key: "tabs.sample" },
      icon: "📦",
      position: 20,
      module: module.id,
      component: SampleTab,
    });

    ui.sections.register({
      area: "profile.sections",
      id: "sample-summary",
      label: { namespace: "module." + module.id, key: "sections.summary" },
      position: 30,
      module: module.id,
      component: SampleSummary,
    });

    ui.sections.register({
      area: "dashboard.widgets",
      id: "sample-stats",
      label: { namespace: "module." + module.id, key: "widgets.quickStats" },
      position: 10,
      module: module.id,
      component: SampleWidget,
    });
  },
};

export default module;
