/**
 * Shim React JSX runtime — pasangan dari `src/shims/react.ts`.
 * esbuild `--jsx=automatic` memancarkan `import { jsx, jsxs, Fragment }`
 * dari specifier ini; kita arahkan via `--alias:react/jsx-runtime=...`
 * ke global host supaya elemen modul dibuat oleh React host.
 */
import type { ReactElement } from "react";

type ReactType = typeof import("react");

const g = globalThis as { __SPINE__?: { react?: unknown } };
const R = g.__SPINE__?.react as unknown as ReactType;

export const Fragment = R.Fragment;

export function jsx(
  type: unknown,
  props: Record<string, unknown> | null,
  key?: string | number | null
): ReactElement {
  return R.createElement(type as never, { ...props, key } as never);
}

export const jsxs = jsx;
export const jsxDEV = jsx;